20	#define SBI_CALL(which, arg0, arg1, arg2)                     \
21	    ({                                                        \
22	        register uintptr_t a0 asm("a0") = (uintptr_t)(arg0);  \
23	        register uintptr_t a1 asm("a1") = (uintptr_t)(arg1);  \
24	        register uintptr_t a2 asm("a2") = (uintptr_t)(arg2);  \
25	        register uintptr_t a7 asm("a7") = (uintptr_t)(which); \
26	        asm volatile("ecall"                                  \
27	                     : "+r"(a0)                               \
28	                     : "r"(a1), "r"(a2), "r"(a7)              \
29	                     : "memory");                             \
30	        a0;                                                   \
31	    })
32	
33	/* Lazy implementations until SBI is finalized */
34	#define SBI_CALL_0(which) SBI_CALL(which, 0, 0, 0)
35	#define SBI_CALL_1(which, arg0) SBI_CALL(which, arg0, 0, 0)
36	#define SBI_CALL_2(which, arg0, arg1) \
37	    SBI_CALL(which, arg0, arg1, 0)
38	#define SBI_CALL_3(which, arg0, arg1, arg2) \
39	    SBI_CALL(which, arg0, arg1, arg2)
