58	static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point, pcb_t *pcb)
59	{
60	    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
61	    pcb->kernel_sp -= sizeof(regs_context_t);
62	
63	    /* initialization registers: ra, sp, gp, sepc, sstatus, sepc, sscratch */
64	    pt_regs->regs[1] = (reg_t)entry_point;      //ra
65	    pt_regs->regs[2] = (reg_t)user_stack;       //sp
66	    pt_regs->regs[3] = (reg_t)__global_pointer$;//gp
67	    pt_regs->sstatus = (reg_t)SR_SPIE;          //SPP = 0, SPIE = 1
68	    pt_regs->sepc = (reg_t)entry_point;         //sepc
69	    pt_regs->sscratch = (reg_t)pcb;             //sscratch = tp
70	}
