57	static unsigned int mini_itoa(
58	    long value, unsigned int radix, unsigned int uppercase,
59	    unsigned int unsig, char *buffer, unsigned int zero_pad)
60	{
61	    char *pbuffer = buffer;
62	    int negative  = 0;
63	    unsigned int i, len;
64	
65	    /* No support for unusual radixes. */
66	    if (radix > 16) return 0;
67	
68	    if (value < 0 && !unsig) {
69	        negative = 1;
70	        value    = -value;
71	    }
72	
73	    /* This builds the string back to front ... */
74	    do {
75	        int digit = 0;
76	        if (unsig) {
77	            digit = (unsigned long)value % (unsigned)radix;
78	        } else {
79	            digit = value % radix;
80	        }
81	        *(pbuffer++) =
82	            (digit < 10 ? '0' + digit :
83	                          (uppercase ? 'A' : 'a') + digit - 10);
84	        if (unsig) {
85	            value = (unsigned long) value / (unsigned) radix;
86	        } else {
87	            value /= radix;
88	        }
89	    } while (value != 0);
90	
91	    for (i = (pbuffer - buffer); i < zero_pad; i++)
92	        *(pbuffer++) = '0';
93	
94	    if (negative) *(pbuffer++) = '-';
95	
96	    *(pbuffer) = '\0';
97	
98	    /* ... now we reverse it (could do it recursively but will
99	     * conserve the stack space) */
100	    len = (pbuffer - buffer);
101	    for (i = 0; i < len / 2; i++) {
102	        char j              = buffer[i];
103	        buffer[i]           = buffer[len - i - 1];
104	        buffer[len - i - 1] = j;
105	    }
106	
107	    return len;
108	}
