110	struct mini_buff
111	{
112	    char *buffer, *pbuffer;
113	    unsigned int buffer_len;
114	};
115	
116	static int _putc(int ch, struct mini_buff *b)
117	{
118	    if ((unsigned int)((b->pbuffer - b->buffer) + 1) >=
119	        b->buffer_len)
120	        return 0;
121	    *(b->pbuffer++) = ch;
122	    *(b->pbuffer)   = '\0';
123	    return 1;
124	}
125	
126	static int _puts(char *s, unsigned int len, struct mini_buff *b)
127	{
128	    unsigned int i;
129	
130	    if (b->buffer_len - (b->pbuffer - b->buffer) - 1 < len)
131	        len = b->buffer_len - (b->pbuffer - b->buffer) - 1;
132	
133	    /* Copy to buffer */
134	    for (i = 0; i < len; i++) *(b->pbuffer++) = s[i];
135	    *(b->pbuffer) = '\0';
136	
137	    return len;
138	}
