140	static int mini_vsnprintf(
141	    char *buffer, unsigned int buffer_len, const char *fmt,
142	    va_list va)
143	{
144	    struct mini_buff b;
145	    char bf[24];
146	    char ch;
147	
148	    b.buffer     = buffer;
149	    b.pbuffer    = buffer;
150	    b.buffer_len = buffer_len;
151	
152	    while ((ch = *(fmt++))) {
153	        if ((unsigned int)((b.pbuffer - b.buffer) + 1) >=
154	            b.buffer_len)
155	            break;
156	        if (ch != '%')
157	            _putc(ch, &b);
158	        else {
159	            char zero_pad = 0;
160	            int longflag = 0;
161	            char *ptr;
162	            unsigned int len;
163	
164	            ch = *(fmt++);
165	
166	            /* Zero padding requested */
167	            if (ch == '0') {
168	                while ((ch = *(fmt++))) {
169	                    if (ch == '\0') goto end;
170	                    if (ch >= '0' && ch <= '9') {
171	                        zero_pad = zero_pad * 10 + ch - '0';
172	                    } else {
173	                        break;
174	                    }
175	                }
176	            }
177	            if (ch == 'l') {
178	                longflag = 1;
179	                ch = *(fmt++);
180	            }
181	
182	            switch (ch) {
183	                case 0:
184	                    goto end;
185	
186	                case 'l':
187	                    longflag = 1;
188	                    break;
189	
190	                case 'u':
191	                case 'd':
192	                    len = mini_itoa(
193	                        longflag == 0 ? (unsigned long)va_arg(
194	                                            va, unsigned int) :
195	                                        va_arg(va, unsigned long),
196	                        10, 0, (ch == 'u'), bf, zero_pad);
197	                    _puts(bf, len, &b);
198	                    longflag = 0;
199	                    break;
200	                case 'x':
201	                case 'X':
202	                    len = mini_itoa(
203	                        longflag == 0 ? (unsigned long)va_arg(
204	                                            va, unsigned int) :
205	                                        va_arg(va, unsigned long),
206	                        16, (ch == 'X'), 1, bf, zero_pad);
207	                    _puts(bf, len, &b);
208	                    longflag = 0;
209	                    break;
210	
211	                case 'c':
212	                    _putc((char)(va_arg(va, int)), &b);
213	                    break;
214	
215	                case 's':
216	                    ptr = va_arg(va, char *);
217	                    _puts(ptr, mini_strlen(ptr), &b);
218	                    break;
219	
220	                default:
221	                    _putc(ch, &b);
222	                    break;
223	            }
224	        }
225	    }
226	end:
227	    return b.pbuffer - b.buffer;
228	}
