230	static int _vprint(const char* fmt, va_list _va,
231	                   void (*output)(char*))
232	{
233	    va_list va;
234	    va_copy(va, _va);
235	
236	    int ret;
237	    char buff[256];
238	
239	    ret = mini_vsnprintf(buff, 256, fmt, va);
240	
241	    buff[ret] = '\0';
242	
243	    output(buff);
244	
245	    return ret;
246	}
