116	/*
117	 * This function is used to print the serial port when the clock
118	 * interrupt is triggered. However, we need to pay attention to
119	 * the fact that in order to speed up printing, we only refresh
120	 * the characters that have been modified since this time.
121	 */
122	void screen_reflush(void)
123	{
124	    int i, j;
125	
126	    /* here to reflush screen buffer to serial port */
127	    for (i = 0; i < SCREEN_HEIGHT; i++){
128	        for (j = 0; j < SCREEN_WIDTH; j++){
129	            /* We only print the data of the modified location. */
130	            if (new_screen[i * SCREEN_WIDTH + j] != old_screen[i * SCREEN_WIDTH + j]){
131	                vt100_move_cursor(j + 1, i + 1);
132	                port_write_ch(new_screen[i * SCREEN_WIDTH + j]);
133	                old_screen[i * SCREEN_WIDTH + j] = new_screen[i * SCREEN_WIDTH + j];
134	            }
135	        }
136	    }
137	
138	    /* recover cursor position */
139	    vt100_move_cursor(screen_cursor_x[cpu_id], screen_cursor_y[cpu_id]);
140	}

