80	    if(src == 0){
81	        *dest = '0';
82	        *(dest + 1) = '\0';
83	        return;
84	    }
85	
86	    int i = 0, j = 0;
87	    while(src){
88	        *(dest + i) = src % 10 + '0';
89	        src /= 10; 
90	        i++;
91	    }
92	    *(dest + i) = '\0';
93	    i--;
94	
95	    char tmp;
96	    while(i>j){
97	        tmp = *(dest + j);
98	        *(dest + j) = *(dest + i);
99	        *(dest + i) = tmp;
100	        i--;
101	        j++;
102	    }
103	}

